import{registerAction}from"@/app/actions";import{getMessages}from"@/lib/i18n-server";const formStartedAt=Date.now();export default async function Register(){const m=await getMessages();return <section className="auth"><form action={registerAction} className="panel"><span className="eyebrow">{m.authors}</span><h1>{m.registerTitle}</h1><input type="hidden" name="startedAt" value={formStartedAt}/><input className="hp" name="website" tabIndex={-1}/><label>{m.authorName}<input name="displayName" minLength={2} required/></label><label>Email<input name="email" type="email" required/></label><label>{m.password}<input name="password" type="password" minLength={10} required/><small>{m.passwordHint}</small></label><button>{m.register}</button></form></section>}